from typing import Optional

from fastapi import FastAPI
from fastapi.testclient import TestClient
from pydantic import BaseModel


class Item(BaseModel):
    name: str
    description: Optional[str] = None
    price: Optional[float] = None


def test_app_default_true_excludes_none():
    """With `default_response_model_exclude_none=True`, a route that does not
    explicitly set `response_model_exclude_none` should drop fields whose
    value is `None`."""
    app = FastAPI(default_response_model_exclude_none=True)

    @app.get("/item", response_model=Item)
    def get_item():
        return Item(name="widget", description=None, price=None)

    client = TestClient(app)
    response = client.get("/item")

    assert response.status_code == 200
    assert response.json() == {"name": "widget"}


def test_app_default_false_includes_none():
    """With the default `default_response_model_exclude_none=False`, a route
    that does not explicitly set `response_model_exclude_none` should keep
    `None`-valued fields in the response."""
    app = FastAPI()

    @app.get("/item", response_model=Item)
    def get_item():
        return Item(name="widget", description=None, price=None)

    client = TestClient(app)
    response = client.get("/item")

    assert response.status_code == 200
    assert response.json() == {
        "name": "widget",
        "description": None,
        "price": None,
    }


def test_explicit_per_route_overrides_app_default():
    """A per-route explicit `response_model_exclude_none=False` should
    override the app-level default of `True` for that route only."""
    app = FastAPI(default_response_model_exclude_none=True)

    @app.get(
        "/item-default",
        response_model=Item,
    )
    def get_item_default():
        # Inherits the app-level default: None fields are excluded.
        return Item(name="widget", description=None, price=None)

    @app.get(
        "/item-explicit",
        response_model=Item,
        response_model_exclude_none=False,
    )
    def get_item_explicit():
        # Explicit override: None fields are kept.
        return Item(name="widget", description=None, price=None)

    client = TestClient(app)

    response_default = client.get("/item-default")
    assert response_default.status_code == 200
    assert response_default.json() == {"name": "widget"}

    response_explicit = client.get("/item-explicit")
    assert response_explicit.status_code == 200
    assert response_explicit.json() == {
        "name": "widget",
        "description": None,
        "price": None,
    }


def test_explicit_per_route_true_with_default_false():
    """A per-route explicit `response_model_exclude_none=True` should also
    override the app-level default of `False`."""
    app = FastAPI(default_response_model_exclude_none=False)

    @app.get(
        "/item-keep",
        response_model=Item,
    )
    def get_item_keep():
        return Item(name="widget", description=None, price=None)

    @app.get(
        "/item-strip",
        response_model=Item,
        response_model_exclude_none=True,
    )
    def get_item_strip():
        return Item(name="widget", description=None, price=None)

    client = TestClient(app)

    response_keep = client.get("/item-keep")
    assert response_keep.status_code == 200
    assert response_keep.json() == {
        "name": "widget",
        "description": None,
        "price": None,
    }

    response_strip = client.get("/item-strip")
    assert response_strip.status_code == 200
    assert response_strip.json() == {"name": "widget"}

